CREATE TABLE ipo_source(id BIGINT AUTO_INCREMENT PRIMARY KEY,ipo_id BIGINT NOT NULL,source_name VARCHAR(255) NOT NULL,source_url VARCHAR(1000) NOT NULL,source_type VARCHAR(30) NOT NULL,reliability VARCHAR(30) NOT NULL,retrieved_at TIMESTAMP(6) NOT NULL,effective_at TIMESTAMP(6),content_hash VARCHAR(64),CONSTRAINT fk_source_ipo FOREIGN KEY(ipo_id) REFERENCES ipo(id),INDEX idx_source_ipo(ipo_id,retrieved_at));
CREATE TABLE ipo_risk(id BIGINT AUTO_INCREMENT PRIMARY KEY,ipo_id BIGINT NOT NULL,severity VARCHAR(20) NOT NULL,category VARCHAR(100) NOT NULL,description VARCHAR(2000) NOT NULL,document_page INT,source_url VARCHAR(1000),hard_override BOOLEAN NOT NULL DEFAULT FALSE,CONSTRAINT fk_risk_ipo FOREIGN KEY(ipo_id) REFERENCES ipo(id),INDEX idx_risk_ipo(ipo_id,severity));
CREATE TABLE ipo_valuation(id BIGINT AUTO_INCREMENT PRIMARY KEY,ipo_id BIGINT NOT NULL UNIQUE,market_cap_crore DECIMAL(19,2),enterprise_value_crore DECIMAL(19,2),pe_ratio DECIMAL(19,4),price_to_book DECIMAL(19,4),ev_ebitda DECIMAL(19,4),ev_sales DECIMAL(19,4),sector_median_pe DECIMAL(19,4),valuation_premium_pct DECIMAL(19,2),calculated_at TIMESTAMP(6) NOT NULL,CONSTRAINT fk_valuation_ipo FOREIGN KEY(ipo_id) REFERENCES ipo(id));
CREATE TABLE ipo_document(id BIGINT AUTO_INCREMENT PRIMARY KEY,ipo_id BIGINT NOT NULL,document_type VARCHAR(20) NOT NULL,source_url VARCHAR(1000) NOT NULL,sha256 VARCHAR(64),page_count INT,extracted_text LONGTEXT,retrieved_at TIMESTAMP(6) NOT NULL,CONSTRAINT fk_document_ipo FOREIGN KEY(ipo_id) REFERENCES ipo(id));
CREATE TABLE ipo_analysis(id BIGINT AUTO_INCREMENT PRIMARY KEY,ipo_id BIGINT NOT NULL,overall_score INT NOT NULL,confidence_score INT NOT NULL,recommendation VARCHAR(40) NOT NULL,listing_recommendation VARCHAR(40),long_term_recommendation VARCHAR(40),engine_version VARCHAR(50) NOT NULL,scoring_version VARCHAR(50) NOT NULL,score_breakdown JSON,summary VARCHAR(3000),analyzed_at TIMESTAMP(6) NOT NULL,CONSTRAINT fk_analysis_ipo FOREIGN KEY(ipo_id) REFERENCES ipo(id),INDEX idx_analysis_history(ipo_id,analyzed_at));
CREATE TABLE analysis_job(id VARCHAR(36) PRIMARY KEY,ipo_id BIGINT,type VARCHAR(20) NOT NULL,status VARCHAR(20) NOT NULL,message VARCHAR(1000),created_at TIMESTAMP(6) NOT NULL,completed_at TIMESTAMP(6));

